// Approach: Keep the top index one past the last value. Push writes at that index; pop decreases it.
//   A fixed-capacity array ignores pushes when full.
#include <vector>
using namespace std;
class ArrayStack {
    vector<int> data;
    int size_ = 0;
public:
    explicit ArrayStack(int capacity) : data(capacity) {}
    // Capacity is nonnegative; pop/top return -1 when empty.
    void push(int value) {
        if (size_ == (int)data.size()) return; // full: ignore push
        data[size_++] = value;
    }
    int pop() {
        if (size_ == 0) return -1; // empty stack
        return data[--size_];
    }
    int top() const {
        if (size_ == 0) return -1; // empty stack
        return data[size_ - 1];
    }
    bool empty() const { return size_ == 0; }
    int size() const { return size_; }
};

