// Approach: Use a circular array: front points to the first element and size tracks occupancy. Wrap
//   the insert position modulo capacity.
#include <vector>
using namespace std;
class CircularQueue {
    vector<int> data;
    int front_ = 0, size_ = 0;
public:
    explicit CircularQueue(int capacity) : data(capacity) {}
    // Capacity is positive; pop/front return -1 when empty.
    void push(int value) {
        if (size_ == (int)data.size()) return; // full: ignore push
        data[(front_ + size_) % data.size()] = value;
        ++size_;
    }
    int pop() {
        if (size_ == 0) return -1; // empty queue
        int value = data[front_];
        front_ = (front_ + 1) % data.size();
        --size_;
        return value;
    }
    int front() const {
        if (size_ == 0) return -1; // empty queue
        return data[front_];
    }
    bool empty() const { return size_ == 0; }
    int size() const { return size_; }
};

