// Approach: After pushing a new value into one queue, rotate every older value behind it. The new
//   value then sits at the front as the stack top.
#include <queue>
using namespace std;
class StackWithQueue {
    queue<int> q;
public:
    void push(int value) {
        q.push(value);
        for (int i = 0, old = (int)q.size() - 1; i < old; ++i) {
            q.push(q.front());
            q.pop();
        }
    }
    int pop() {
        if (q.empty()) return -1; // empty stack
        int value = q.front();
        q.pop();
        return value;
    }
    int top() const {
        if (q.empty()) return -1; // empty stack
        return q.front();
    }
    bool empty() const { return q.empty(); }
};

