// Approach: Push into an input stack. For front/pop, move input to output only when output is empty;
//   each item moves at most once.
#include <stack>
using namespace std;
class QueueWithStacks {
    stack<int> input, output;
    void refill() {
        if (!output.empty()) return;
        while (!input.empty()) {
            output.push(input.top());
            input.pop();
        }
    }
public:
    void push(int value) { input.push(value); }
    int front() {
        refill();
        if (output.empty()) return -1; // empty queue
        return output.top();
    }
    int pop() {
        refill();
        if (output.empty()) return -1; // empty queue
        int value = output.top();
        output.pop();
        return value;
    }
    bool empty() const { return input.empty() && output.empty(); }
};

