// Approach: Treat the linked-list head as the stack top. Push and pop change only the head link.
using namespace std;
class LinkedStack {
    struct Node { int value; Node* next; };
    Node* head = nullptr;
public:
    LinkedStack() = default;
    LinkedStack(const LinkedStack&) = delete;
    LinkedStack& operator=(const LinkedStack&) = delete;
    ~LinkedStack() { while (head) pop(); }
    void push(int value) { head = new Node{value, head}; }
    int pop() {
        if (!head) return -1; // empty stack
        Node* old = head;
        int value = old->value;
        head = old->next;
        delete old;
        return value;
    }
    int top() const {
        if (!head) return -1; // empty stack
        return head->value;
    }
    bool empty() const { return head == nullptr; }
};

