// Approach: Keep both head and tail pointers. Enqueue at the tail and dequeue at the head; reset tail
//   when the queue becomes empty.
using namespace std;
class LinkedQueue {
    struct Node { int value; Node* next; };
    Node* head = nullptr;
    Node* tail = nullptr;
public:
    LinkedQueue() = default;
    LinkedQueue(const LinkedQueue&) = delete;
    LinkedQueue& operator=(const LinkedQueue&) = delete;
    ~LinkedQueue() { while (head) pop(); }
    void push(int value) {
        Node* node = new Node{value, nullptr};
        if (tail) tail->next = node;
        else head = node;
        tail = node;
    }
    int pop() {
        if (!head) return -1; // empty queue
        Node* old = head;
        int value = old->value;
        head = old->next;
        if (!head) tail = nullptr;
        delete old;
        return value;
    }
    int front() const {
        if (!head) return -1; // empty queue
        return head->value;
    }
    bool empty() const { return head == nullptr; }
};

s9-check-for-balanced-paranthesis.code:
// Approach: Push opening brackets. Each closing bracket must match the latest unmatched opening
//   bracket; the stack must be empty at the end.
#include <stack>
#include <string>
using namespace std;
bool balancedBrackets(const string& s) {
    // A closing bracket must match the most recently opened bracket.
    stack<char> open;
    for (char ch : s) {
        if (ch == '(' || ch == '[' || ch == '{') open.push(ch);
        else if (ch == ')' || ch == ']' || ch == '}') {
            if (open.empty()) return false;
            char need = ch == ')' ? '(' : (ch == ']' ? '[' : '{');
            if (open.top() != need) return false;
            open.pop();
        }
    }
    return open.empty();
}

