// Approach: Store the minimum so far alongside every pushed value. Then top, pop, and getMin all take
//   constant time.
#include <algorithm>
#include <vector>
#include <utility>
using namespace std;
class MinStack {
    vector<pair<int,int>> data;
public:
    void push(int value) {
        int minimum = data.empty() ? value : min(value, data.back().second);
        data.push_back({value, minimum});
    }
    void pop() {
        if (data.empty()) return; // no value to pop
        data.pop_back();
    }
    int top() const {
        if (data.empty()) return -1; // empty stack
        return data.back().first;
    }
    int getMin() const {
        if (data.empty()) return -1; // empty stack
        return data.back().second;
    }
};

s9-infix-to-postfix-conversion-using-sta.code:
// Approach: Send operands directly to output. Hold operators on a stack, popping higher precedence
//   first; '^' is right-associative.
// Input is a valid expression with single-character operands.
#include <cctype>
#include <stack>
#include <string>
using namespace std;
int precedence(char op) {
    if (op == '^') return 3;
    if (op == '*' || op == '/') return 2;
    if (op == '+' || op == '-') return 1;
    return -1;
}
string infixToPostfix(const string& expr) {
    stack<char> ops;
    string output;
    for (char ch : expr) {
        if (isspace((unsigned char)ch)) continue;
        if (isalnum((unsigned char)ch)) output += ch;
        else if (ch == '(') ops.push(ch);
        else if (ch == ')') {
            while (!ops.empty() && ops.top() != '(') {
                output += ops.top(); ops.pop();
            }
            ops.pop();
        } else if (precedence(ch) >= 0) {
            // Pop stronger operators before pushing the new one.
            while (!ops.empty() && ops.top() != '(' &&
                   (precedence(ops.top()) > precedence(ch) ||
                   (precedence(ops.top()) == precedence(ch) && ch != '^'))) {
                output += ops.top(); ops.pop();
            }
            ops.push(ch);
        }
    }
    while (!ops.empty()) {
        output += ops.top(); ops.pop();
    }
    return output; // single-character operands, binary operators
}

