// Approach: Scan prefix right to left. Push operands; for an operator, pop left then right and wrap
//   their infix form in parentheses.
// Input is a valid expression with single-character operands.
#include <cctype>
#include <stack>
#include <string>
using namespace std;
string prefixToInfix(const string& prefix) {
    // Read backward so both operands are ready when an operator appears.
    stack<string> parts;
    for (int i = (int)prefix.size() - 1; i >= 0; --i) {
        char ch = prefix[i];
        if (isspace((unsigned char)ch)) continue;
        if (isalnum((unsigned char)ch)) parts.push(string(1, ch));
        else if (ch == '+' || ch == '-' || ch == '*' || ch == '/' || ch == '^') {
            string left = parts.top(); parts.pop();
            string right = parts.top(); parts.pop();
            parts.push("(" + left + ch + right + ")");
        }
    }
    return parts.top();
}

