s9-convert-infix-to-prefix-notation.code:
// Approach: Use operator and expression stacks. Apply higher-precedence operators first, building
//   operator+left+right; keep '^' right-associative.
// Input is a valid expression with single-character operands.
#include <cctype>
#include <stack>
#include <string>
using namespace std;
int priority(char op) {
    if (op == '^') return 3;
    if (op == '*' || op == '/') return 2;
    if (op == '+' || op == '-') return 1;
    return -1;
}
void applyTop(stack<char>& ops, stack<string>& values) {
    char op = ops.top(); ops.pop();
    string right = values.top(); values.pop();
    string left = values.top(); values.pop();
    values.push(op + left + right);
}
string infixToPrefix(const string& expr) {
    stack<char> ops;
    stack<string> values;
    for (char ch : expr) {
        if (isspace((unsigned char)ch)) continue;
        if (isalnum((unsigned char)ch)) values.push(string(1, ch));
        else if (ch == '(') ops.push(ch);
        else if (ch == ')') {
            while (!ops.empty() && ops.top() != '(') applyTop(ops, values);
            ops.pop();
        } else if (priority(ch) >= 0) {
            // Apply operators that must happen before the current operator.
            while (!ops.empty() && ops.top() != '(' &&
                   (priority(ops.top()) > priority(ch) ||
                   (priority(ops.top()) == priority(ch) && ch != '^')))
                applyTop(ops, values);
            ops.push(ch);
        }
    }
    while (!ops.empty()) {
        applyTop(ops, values);
    }
    return values.top(); // single-character operands, binary operators
}

s9-next-greater-element.code:
// Approach: Scan from right to left with a decreasing stack. Remove values no greater than the
//   current one; the remaining top is its next greater value.
#include <vector>
using namespace std;
vector<int> nextGreater(const vector<int>& a) {
    // Discard smaller stack values because they cannot answer future positions.
    int n = (int)a.size();
    vector<int> answer(n, -1), stack;
    for (int i = n - 1; i >= 0; --i) {
        while (!stack.empty() && stack.back() <= a[i]) stack.pop_back();
        if (!stack.empty()) answer[i] = stack.back();
        stack.push_back(a[i]);
    }
    return answer;
}

