// Approach: For a circular array, scan indices 2n-1 down to 0 and index modulo n. The second pass
//   supplies candidates beyond the physical end.
#include <vector>
using namespace std;
vector<int> nextGreaterCircular(const vector<int>& a) {
    // Scan twice so values near the end can see values near the start.
    int n = (int)a.size();
    vector<int> answer(n, -1), stack;
    if (n == 0) return answer;
    for (int i = 2 * n - 1; i >= 0; --i) {
        int value = a[i % n];
        while (!stack.empty() && stack.back() <= value) stack.pop_back();
        if (i < n && !stack.empty()) answer[i] = stack.back();
        stack.push_back(value);
    }
    return answer;
}

