s9-number-of-nges-to-the-right.code:
// Approach: Scan the array from right to left. A Fenwick tree counts values already seen; subtract
//   the count of values <= a[i] to get greater values to the right.
#include <algorithm>
#include <vector>
using namespace std;
struct Fenwick {
    // Count all qualifying values to the right of each query index.
    vector<int> bit;
    explicit Fenwick(int n) : bit(n + 1, 0) {}
    void add(int index) {
        for (; index < (int)bit.size(); index += index & -index)
            ++bit[index];
    }
    int prefix(int index) const {
        int count = 0;
        for (; index > 0; index -= index & -index)
            count += bit[index];
        return count;
    }
};
vector<int> countGreaterToRight(const vector<int>& a,
                                const vector<int>& queries) {
    vector<int> sorted = a;
    sort(sorted.begin(), sorted.end());
    sorted.erase(unique(sorted.begin(), sorted.end()), sorted.end());
    Fenwick seen((int)sorted.size());
    vector<int> count(a.size());
    // Process from right to left so the Fenwick tree contains only later values.
    for (int i = (int)a.size() - 1; i >= 0; --i) {
        int rank = (int)(lower_bound(sorted.begin(), sorted.end(), a[i])
                         - sorted.begin()) + 1;
        count[i] = (int)a.size() - 1 - i - seen.prefix(rank);
        seen.add(rank);
    }
    vector<int> answer;
    for (int index : queries)
        answer.push_back(index >= 0 && index < (int)a.size() ? count[index] : 0);
    return answer;
}

s9-trapping-rainwater.code:
// Approach: The lower of the two boundary heights limits water on its side. Move that pointer inward,
//   tracking its best boundary.
#include <algorithm>
#include <vector>
using namespace std;
long long trapWater(const vector<int>& height) {
    // Water above a bar depends on the shorter of its left and right walls.
    int left = 0, right = (int)height.size() - 1;
    int leftMax = 0, rightMax = 0;
    long long water = 0;
    while (left <= right) {
        if (height[left] <= height[right]) {
            leftMax = max(leftMax, height[left]);
            water += leftMax - height[left];
            ++left;
        } else {
            rightMax = max(rightMax, height[right]);
            water += rightMax - height[right];
            --right;
        }
    }
    return water;
}

s9-sum-of-subarray-minimum.code:
// Approach: For each element, count subarrays where it is the chosen minimum. A monotonic stack finds
//   the previous strictly smaller and next smaller-or-equal boundaries.
#include <vector>
using namespace std;
int sumSubarrayMins(const vector<int>& a) {
    // Count how many subarrays choose each element as their minimum.
    const long long MOD = 1000000007;
    int n = (int)a.size();
    vector<int> stack;
    long long answer = 0;
    for (int right = 0; right <= n; ++right) {
        while (!stack.empty() && (right == n || a[stack.back()] >= a[right])) {
            int mid = stack.back();
            stack.pop_back();
            int left = stack.empty() ? -1 : stack.back();
            long long ways = 1LL * (mid - left) * (right - mid);
            answer = (answer + ways % MOD * a[mid]) % MOD;
        }
        stack.push_back(right);
    }
    return (int)((answer + MOD) % MOD);
}

s9-asteroid-collision.code:
// Approach: A collision is possible only when a right-moving survivor meets a new left-moving
//   asteroid. Resolve larger magnitudes until one side survives.
#include <vector>
using namespace std;
vector<int> asteroidCollision(const vector<int>& asteroids) {
    // Only a right-moving asteroid can collide with a later left-moving one.
    vector<int> survivors;
    for (int x : asteroids) {
        bool alive = true;
        while (alive && x < 0 && !survivors.empty() && survivors.back() > 0) {
            long long right = survivors.back();
            long long left = -(long long)x;
            if (right < left) survivors.pop_back();
            else {
                if (right == left) survivors.pop_back();
                alive = false;
            }
        }
        if (alive) survivors.push_back(x);
    }
    return survivors;
}

s9-sum-of-subarray-ranges.code:
// Approach: Compute each element's contribution as a subarray maximum and as a minimum, using
//   monotonic stacks; subtract the two sums.
#include <vector>
using namespace std;
long long contributionSum(const vector<int>& a, bool maximum) {
    // Each element contributes as a maximum and subtracts as a minimum.
    int n = (int)a.size();
    vector<int> stack;
    long long total = 0;
    for (int right = 0; right <= n; ++right) {
        while (!stack.empty() &&
               (right == n || (maximum ? a[stack.back()] <= a[right]
                                       : a[stack.back()] >= a[right]))) {
            int mid = stack.back();
            stack.pop_back();
            int left = stack.empty() ? -1 : stack.back();
            total += 1LL * a[mid] * (mid - left) * (right - mid);
        }
        stack.push_back(right);
    }
    return total;
}
long long subarrayRanges(const vector<int>& a) {
    return contributionSum(a, true) - contributionSum(a, false);
}

s9-remove-k-digits.code:
// Approach: Maintain a nondecreasing digit stack. When a smaller digit arrives, remove larger
//   preceding digits while removals remain; strip leading zeroes at the end.
#include <string>
using namespace std;
string removeKdigits(const string& digits, int k) {
    // Remove a larger previous digit when a smaller new digit arrives.
    string kept;
    for (char digit : digits) {
        while (k > 0 && !kept.empty() && kept.back() > digit) {
            kept.pop_back();
            --k;
        }
        kept.push_back(digit);
    }
    while (k > 0 && !kept.empty()) { kept.pop_back(); --k; }
    int first = 0;
    while (first < (int)kept.size() && kept[first] == '0') ++first;
    return first == (int)kept.size() ? "0" : kept.substr(first);
}

s9-largest-rectangle-in-a-histogram.code:
// Approach: Keep increasing bar indices. When a shorter bar appears, pop taller bars and use the new
//   top as each popped bar's left boundary.
#include <algorithm>
#include <vector>
using namespace std;
long long largestRectangle(const vector<int>& height) {
    // A shorter bar ends rectangles started by taller bars.
    int n = (int)height.size();
    vector<int> stack;
    long long best = 0;
    for (int right = 0; right <= n; ++right) {
        while (!stack.empty() && (right == n || height[stack.back()] >= height[right])) {
            int mid = stack.back();
            stack.pop_back();
            int left = stack.empty() ? -1 : stack.back();
            best = max(best, 1LL * height[mid] * (right - left - 1));
        }
        stack.push_back(right);
    }
    return best;
}

s9-maximal-rectangles.code:
// Approach: Treat each row as the base of a histogram of consecutive 1s above it. The largest
//   histogram rectangle over all rows is the answer.
#include <algorithm>
#include <vector>
using namespace std;
long long histogramArea(const vector<int>& height) {
    // Treat each matrix row as a histogram of consecutive ones.
    vector<int> stack;
    long long best = 0;
    for (int right = 0; right <= (int)height.size(); ++right) {
        while (!stack.empty() &&
               (right == (int)height.size() || height[stack.back()] >= height[right])) {
            int mid = stack.back();
            stack.pop_back();
            int left = stack.empty() ? -1 : stack.back();
            best = max(best, 1LL * height[mid] * (right - left - 1));
        }
        stack.push_back(right);
    }
    return best;
}
long long maximalRectangle(const vector<vector<char>>& matrix) {
    if (matrix.empty()) return 0;
    vector<int> height(matrix[0].size(), 0);
    long long best = 0;
    for (const auto& row : matrix) {
        for (int c = 0; c < (int)row.size(); ++c)
            height[c] = row[c] == '1' ? height[c] + 1 : 0;
        best = max(best, histogramArea(height));
    }
    return best;
}

s9-sliding-window-maximum.code:
// Approach: Keep indices in a deque with decreasing values. Drop indices outside the window; the
//   front is its maximum.
#include <deque>
#include <vector>
using namespace std;
vector<int> maxSlidingWindow(const vector<int>& a, int k) {
    // The deque stores indices whose values can still become window maxima.
    vector<int> answer;
    if (k <= 0 || k > (int)a.size()) return answer;
    deque<int> dq;
    for (int i = 0; i < (int)a.size(); ++i) {
        while (!dq.empty() && dq.front() <= i - k) dq.pop_front();
        while (!dq.empty() && a[dq.back()] <= a[i]) dq.pop_back();
        dq.push_back(i);
        if (i >= k - 1) answer.push_back(a[dq.front()]);
    }
    return answer;
}

s9-stock-span-problem.code:
// Approach: Collapse earlier prices no greater than today's price. Each stack item stores its price
//   and the span it already represents.
#include <stack>
#include <utility>
using namespace std;
class StockSpanner {
    // Pop earlier prices no greater than today's price to extend the span.
    stack<pair<int,int>> previous;
public:
    int next(int price) {
        int span = 1;
        while (!previous.empty() && previous.top().first <= price) {
            span += previous.top().second;
            previous.pop();
        }
        previous.push({price, span});
        return span;
    }
};

