// Approach: Eliminate one of each pair: if A knows B, A cannot be the celebrity; otherwise B cannot.
//   Verify the one remaining candidate.
#include <vector>
using namespace std;
int celebrity(const vector<vector<int>>& knows) {
    // Eliminate impossible candidates first, then verify the survivor.
    int n = (int)knows.size();
    if (n == 0) return -1;
    int candidate = 0;
    for (int other = 1; other < n; ++other)
        if (knows[candidate][other]) candidate = other;
    for (int person = 0; person < n; ++person) {
        if (person == candidate) continue;
        if (knows[candidate][person] || !knows[person][candidate])
            return -1;
    }
    return candidate;
}

