// Approach: Use a doubly linked list for recency order and a hash map from key to list iterator. Move
//   accessed keys to the front; evict from the back.
#include <list>
#include <unordered_map>
#include <utility>
using namespace std;
class LRUCache {
    int capacity;
    list<pair<int,int>> recent; // front = most recently used
    unordered_map<int, list<pair<int,int>>::iterator> where;
public:
    explicit LRUCache(int capacity) : capacity(capacity) {}
    int get(int key) {
        auto it = where.find(key);
        if (it == where.end()) return -1;
        recent.splice(recent.begin(), recent, it->second);
        return it->second->second;
    }
    void put(int key, int value) {
        if (capacity <= 0) return;
        auto it = where.find(key);
        if (it != where.end()) {
            it->second->second = value;
            recent.splice(recent.begin(), recent, it->second);
            return;
        }
        if ((int)recent.size() == capacity) {
            where.erase(recent.back().first);
            recent.pop_back();
        }
        recent.push_front({key, value});
        where[key] = recent.begin();
    }
};

