// Approach: Map keys to value/frequency and their position in a frequency list. Evict the least
//   recently used key from the lowest-frequency list.
#include <list>
#include <unordered_map>
using namespace std;
class LFUCache {
    struct Entry { int value, frequency; list<int>::iterator position; };
    int capacity, minimumFrequency = 0;
    unordered_map<int, Entry> items;
    // Each frequency bucket also keeps recent-use order for ties.
    unordered_map<int, list<int>> byFrequency; // front = most recent
    void touch(int key) {
        Entry& entry = items.at(key);
        int old = entry.frequency;
        byFrequency[old].erase(entry.position);
        if (byFrequency[old].empty()) {
            byFrequency.erase(old);
            if (minimumFrequency == old) ++minimumFrequency;
        }
        ++entry.frequency;
        byFrequency[entry.frequency].push_front(key);
        entry.position = byFrequency[entry.frequency].begin();
    }
public:
    explicit LFUCache(int capacity) : capacity(capacity) {}
    int get(int key) {
        auto it = items.find(key);
        if (it == items.end()) return -1;
        int value = it->second.value;
        touch(key);
        return value;
    }
    void put(int key, int value) {
        if (capacity <= 0) return;
        auto it = items.find(key);
        if (it != items.end()) {
            it->second.value = value;
            touch(key);
            return;
        }
        if ((int)items.size() == capacity) {
            int evicted = byFrequency[minimumFrequency].back();
            byFrequency[minimumFrequency].pop_back();
            if (byFrequency[minimumFrequency].empty())
                byFrequency.erase(minimumFrequency);
            items.erase(evicted);
        }
        minimumFrequency = 1;
        byFrequency[1].push_front(key);
        items[key] = {value, 1, byFrequency[1].begin()};
    }
};
